import punycode from 'punycode.js';
import * as mdurl from 'mdurl';

// Test 1: toASCII on Unicode hostname
console.log("=== Test 1: toASCII for ☃.net ===");
try { 
  const result = punycode.toASCII('☃.net');
  console.log('Result:', result);
} catch(e) { 
  console.log('Error:', e.message); 
}

// Test 2: toASCII on 'xn--γ.com' (invalid punycode - mixed)
console.log("\n=== Test 2: toASCII for xn--γ.com ===");
try { 
  const result = punycode.toASCII('xn--γ.com');
  console.log('Result:', result);
} catch(e) { 
  console.log('Error:', e.message); 
}

// Test 3: decode 'xn--' prefix hostname
console.log("\n=== Test 3: normalizeLinkText for xn--n3h ===");
try {
  const parsed = mdurl.parse('http://xn--n3h.net/', true);
  console.log('parsed.hostname before toUnicode:', parsed.hostname);
  try {   
    var unicoded = punycode.toUnicode(parsed.hostname);
    console.log('After toUnicode:', unicoded);
  } catch(e2) { 
    console.log('toUnicode error:', e2.message); 
  }
  console.log('Parsed host part:', parsed.hostname);
} catch(e3) {
  console.log('Error:', e3.message);
}

// Test 4: What about 'xn--γ.com' - the expected output is 'xn--xn---emd.com/'
// Is gamma a valid punycode? Let me check.
console.log("\n=== Test 4: toUnicode for xn--xn---emd ===");
try {
  const result = punycode.toUnicode('xn--xn---emd');
  console.log('Result:', result);
} catch(e) { 
  console.log('Error:', e.message); 
}

// Test 5: What about normalizing 'xn--γ.com' as hostname?
console.log("\n=== Test 5: toUnicode for xn--γ ===");
try {
  const result = punycode.toUnicode('xn--γ');
  console.log('Result:', result);
} catch(e) { 
  console.log('Error:', e.message); 
}

// Test 6: Check what mdurl.normalize does with the hostname
console.log("\n=== Test 6: Full normalizeLinkText for xn--γ.com ===");
{
  // This is what normalize_link_text would do
  const parsed = mdurl.parse('http://xn--γ.com/', true);
  console.log('parsed.hostname:', parsed.hostname);
  let hostname = parsed.hostname;
  try {
    hostname = punycode.toUnicode(hostname);
    console.log('After toUnicode:', hostname);
  } catch(e) {
    console.log('toUnicode error, keeping original');
  }
  const result = mdurl.decode(mdurl.format(parsed), mdurl.decode.defaultChars + '%');
  console.log('Final (no unicode decode):', result);

  // But the test expects: <p><a href="http://xn--xn---emd.com/">http://xn--γ.com</a></p>
  // So the hostname should be 'xn--xn---emd.com' not '%CE%B3.com'
  // This means xn--γ is INVALID punycode and should be left as-is (not encoded)
}

// Test 7: What does normalizeLink do with 'xn--γ.com'?
console.log("\n=== Test 7: Full normalizeLink for xn--γ.com ===");
{
  const parsed = mdurl.parse('http://xn--γ.com/', true);
  console.log('parsed.hostname:', parsed.hostname);
  if (parsed.hostname) {
    try {
      parsed.hostname = punycode.toASCII(parsed.hostname);
      console.log('After toASCII:', parsed.hostname);
    } catch(e) {
      console.log('toASCII error, keeping original');
    }
    const result = mdurl.format(parsed);
    console.log('format before encode:', result);
    parsed.hostname = mdurl.encode(parsed.hostname || '');
    console.log('hostname after encode:', parsed.hostname);
    const finalResult = mdurl.format(parsed);
    console.log('Final normalized link:', finalResult);
  }
}

// Test 8: check toASCII for 'xn--γ' explicitly - this is the key question
console.log("\n=== Test 8: What does punycode.toASCII do with 'xn--γ'? ===");
{
  // The hostname would be parsed from 'http://xn--γ.com/' as 'xn--γ.com'
  // Then toASCII is called on that
  const h = 'xn--γ';
  console.log('Input:', h);

  // Actually, the test says expected href should be 'http://xn--xn---emd.com/'
  // This means: when parsing 'http://xn--γ.com/', the hostname should be decoded 
  // from an invalid punycode. But wait - what about the full domain?
  // The hostname 'xn--γ.com' doesn't look like valid punycode since γ is not ASCII.

  // Let me see if toASCII on 'xn--γ.com' actually decodes it somehow:
  try {
    const r1 = punycode.toASCII('xn--γ.com');
    console.log('toASCII(xn--γ.com):', r1);
  } catch(e) { 
    console.log('Error:', e.message); 
  }

  // The expected output href is xn--xn---emd.com/ - this looks like the decoded form
  // of 'xn--' prefix with 'xn---emd' as the punycode payload.

  // Wait - maybe normalizeLinkText is supposed to handle this too?
  // Let me check what happens:
  {
    const testParsed = mdurl.parse('http://xn--γ.com/', true);
    console.log('\nparse result:', testParsed.hostname);

    // In normalize_link_text, we call toUnicode on the hostname first
    let hostname2 = testParsed.hostname;
    try {
      hostname2 = punycode.toUnicode(hostname2);
      console.log('toUnicode result:', hostname2);
    } catch(e2) {
      console.log('toUnicode error');
    }

    // Then decode with mdurl.decode  
    // mdurl.format(parsed) gives us the URL back, then we decode it
    const formatted = mdurl.format(testParsed);
    console.log('formatted:', formatted);

    const decodedResult = mdurl.decode(formatted, mdurl.decode.defaultChars + '%');
    console.log('decoded with % in exclude:', decodedResult);
  }
}

// Test 9: Compare the behavior of normalize_link_text for 'http://xn--n3h.net/' 
console.log("\n=== Test 9: For valid punycode xn--n3h ===");
{
  const parsed = mdurl.parse('http://xn--n3h.net/', true);
  let hostname = parsed.hostname;
  try {
    hostname = punycode.toUnicode(hostname);
  } catch(e) {}
  console.log('hostname after toUnicode:', hostname);

  const formatted = mdurl.format(parsed);
  const decoded = mdurl.decode(formatted, mdurl.decode.defaultChars + '%');
  console.log('decoded result:', decoded);
}

// Test 10: Now let's look at what fails - the problem is in normalizing_link_text
console.log("\n=== Test 10: What about line 48 case? ===");
{
  // Input URL in test: http://xn--γ.com/
  // Expected href: http://xn--xn---emd.com/
  // Actual (from failing): http://xn--%CE%B3.com/

  // So the bug might be in mdurl.encode or somewhere else...
  // Wait, the issue might actually be about WHAT gets encoded.

  console.log('The hostname from parse:', 'xn--γ.com');
  const parsed = mdurl.parse('http://xn--γ.com/', true);
  console.log('parsed.hostname:', parsed.hostname);
  // The hostname IS 'xn--γ.com' which contains non-ASCII chars

  // In normalize_link, toASCII is called:
  try {
    let r = punycode.toASCII('xn--γ.com');
    console.log('toASCII result:', r);
  } catch(e) { 
    console.log('toASCII error:', e.message); 
  }

  // Then mdurl.encode is applied to the hostname... but by that point
  // the hostname should have been converted. If toASCII fails silently (the try/catch),
  // then the original 'xn--γ.com' gets encoded which becomes 'xn--%CE%B3.com'.

  // But expected output is 'xn--xn---emd.com/'
  // This suggests: when given invalid punycode, we should NOT encode it... wait no.
  // The expected IS punycode: xn--xn---emd (which is the ASCII form of some other string).

  // Hmm let me check: what Unicode does 'xn--γ' resolve to?
  // γ = U+03B3 (Greek lowercase gamma)
  // If we decode via punycode with prefix 'xn--' and payload 'γ',
  // but that's invalid because γ is non-ASCII...

  console.log('\nMaybe the issue is in normalize_link_text, not normalize_link?');

  for (const url of ['http://xn--n3h.net/', 'http://xn--xn---emd.com/', 'http://xn--γ.com/']) {
    const p = mdurl.parse(url, true);
    console.log(`\nURL: ${url}`);
    console.log('  hostname:', p.hostname);
    try {
      p.hostname = punycode.toUnicode(p.hostname);
      console.log('  after toUnicode:', p.hostname);
    } catch(e) {
      console.log('  toUnicode error:', e.message);
    }
    const f = mdurl.format(p);
    const d = mdurl.decode(f, mdurl.decode.defaultChars + '%');
    console.log('  final decoded:', d);
  }
}

console.log("\nDone!");
